commands:
A=/home/jack/.t3/bench-runs-lanes/fable52-thermo/2026-11-20-thermo-nuclear-review-claude-fable-5-2/att-009; W=$A/clone-work/scratch; mkdir -p $W/base $W/head && cd $A/clone && git archive main | tar -x -C $W/base && git archive review-head | tar -x -C $W/head
cat > $W/zz_diff_test.go <<'EOF'
package internal

import (
	"bytes"
	"fmt"
	"log"
	"math/rand"
	"os"
	"testing"
)

func TestZZDifferential(t *testing.T) {
	vars := []string{
		envGitBackupDir, envGitHubToken, envGitHubOrgs, envGitHubSkipUserRepos, envGitHubCompare, envGitHubBackupLFS,
		envGiteaToken, envGiteaOrgs, envGiteaBackups, envGiteaCompare, envGiteaBackupLFS,
		envGitLabToken, envGitLabMinAccessLevel, envGitLabBackups, envGitLabCompare, envGitLabBackupLFS,
		envBitBucketEmail, envBitBucketAPIToken, envBitBucketUser, envBitBucketKey, envBitBucketSecret,
		envBitBucketBackups, envBitBucketCompare, envBitBucketBackupLFS,
		envAzureDevOpsUserName, envAzureDevOpsPAT, envAzureDevOpsOrgs, envAzureDevOpsCompare, envAzureDevOpsBackupLFS,
		envSourcehutToken, envSourcehutAPIURL,
	}
	vals := []string{"", " ", "refs", "REFS", "Refs", "clone", "true", "yes", "Y", "no", "Org1,ORG2", "3", "x"}
	r := rand.New(rand.NewSource(42))
	var out bytes.Buffer
	logger = log.New(&out, "", 0)
	for i := 0; i < 20000; i++ {
		for _, v := range vars {
			os.Unsetenv(v)
			os.Unsetenv(v + "_FILE")
		}
		desc := ""
		for _, v := range vars {
			// bias toward set
			if r.Intn(3) == 0 {
				continue
			}
			val := vals[r.Intn(len(vals))]
			os.Setenv(v, val)
			desc += fmt.Sprintf("%s=%q ", v, val)
		}
		fmt.Fprintf(&out, "CASE %d %s\n", i, desc)
		displayStartupConfig()
		err := checkProvidersDefined()
		if err != nil {
			fmt.Fprintf(&out, "cpd err!=nil\n")
			// error text depends on map order; record sorted lines
			lines := bytes.Split([]byte(err.Error()), []byte("\n"))
			m := map[string]int{}
			for _, l := range lines {
				m[string(l)]++
			}
			for _, p := range []string{providerNameAzureDevOps, providerNameGitHub, providerNameGitLab, providerNameGitea, providerNameSourcehut, providerNameBitBucketAPIToken, providerNameBitBucketOAuth} {
				c, e := 0, error(nil)
				if p != providerNameBitBucketAPIToken && p != providerNameBitBucketOAuth {
					c, e = checkProvider(p)
				}
				fmt.Fprintf(&out, "cp %s %d %v\n", p, c, e)
			}
			fmt.Fprintf(&out, "nlines %d\n", len(m))
			if err.Error() == "no providers defined" {
				fmt.Fprintf(&out, "noproviders\n")
			}
		} else {
			fmt.Fprintf(&out, "cpd ok\n")
			for _, p := range []string{providerNameAzureDevOps, providerNameGitHub, providerNameGitLab, providerNameGitea, providerNameSourcehut} {
				c, e := checkProvider(p)
				fmt.Fprintf(&out, "cp %s %d %v\n", p, c, e)
			}
		}
		for _, sf := range [][2]int{{0, 0}, {1, 0}, {0, 1}, {2, 3}} {
			_ = sf
		}
	}
	if err := os.WriteFile(os.Getenv("ZZ_OUT"), out.Bytes(), 0o600); err != nil {
		t.Fatal(err)
	}
}
EOF
cp $W/zz_diff_test.go $W/base/internal/; cp $W/zz_diff_test.go $W/head/internal/
export GOMODCACHE=$A/clone-cache/gomodcache GOCACHE=$A/clone-cache/gocache GOFLAGS=-mod=mod GOPROXY=off GOTOOLCHAIN=local TMPDIR=$A/tmp
(cd $W/base && ZZ_OUT=$W/base.out go test ./internal/ -run TestZZDifferential -count=1 2>&1 | tail -5)
(cd $W/head && ZZ_OUT=$W/head.out go test ./internal/ -run TestZZDifferential -count=1 2>&1 | tail -5)
wc -l $W/base.out $W/head.out; cmp $W/base.out $W/head.out && echo IDENTICAL; grep -c "cpd ok" $W/head.out; grep -c noproviders $W/head.out; grep -c "compare method: refs" $W/head.out; grep -c "Organistations" $W/head.out; cd $A/clone && git status --short
